WITH src AS (SELECT * FROM suppliers WHERE city IS NULL AND (city = 'Singapore' OR rating > 3.6)), CitySummary AS (SELECT city, CASE WHEN rating >= 4.5 THEN 'high' WHEN rating >= 2.0 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(CASE WHEN city = 'London' THEN 1 END) AS london_count, COUNT(rating) AS rating_count FROM src GROUP BY city, CASE WHEN rating >= 4.5 THEN 'high' WHEN rating >= 2.0 THEN 'mid' ELSE 'low' END) SELECT city, rating_bucket, london_count, rating_count FROM CitySummary ORDER BY city ASC, rating_bucket ASC LIMIT 5;
